-- Finance billing reminders (dunning) -- generated by noctusai_lib.domain.finance.reminders.sql (do not hand-edit)

SET search_path = orbity, public;

-- Per-receivable opt-out (the host's UI flips it; the engine never sends for an opted-out receivable).
ALTER TABLE orbity.fin_entries ADD COLUMN IF NOT EXISTS reminders_opt_out BOOLEAN NOT NULL DEFAULT false;

-- Per-org master switch + timezone. No row = reminders OFF (opt-in: dunning a client is never a surprise default).
CREATE TABLE IF NOT EXISTS orbity.fin_reminder_settings (
    org_id     UUID PRIMARY KEY,
    enabled    BOOLEAN NOT NULL DEFAULT false,
    timezone   TEXT NOT NULL DEFAULT 'America/Sao_Paulo',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE orbity.fin_reminder_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_reminder_settings_select_own_org" ON orbity.fin_reminder_settings;
CREATE POLICY "fin_reminder_settings_select_own_org" ON orbity.fin_reminder_settings FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('orbity')));
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_reminder_settings;
CREATE POLICY "service_role_bypass" ON orbity.fin_reminder_settings FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Rules: one per (org, channel, offset). offset_days is relative to the due date (-3 = three days before).
CREATE TABLE IF NOT EXISTS orbity.fin_reminder_rules (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    channel     TEXT NOT NULL CHECK (channel IN ('whatsapp', 'email')),
    offset_days INTEGER NOT NULL CHECK (offset_days BETWEEN -60 AND 365),
    template    TEXT NOT NULL CHECK (length(btrim(template)) > 0),
    enabled     BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_reminder_rules_offset ON orbity.fin_reminder_rules (org_id, channel, offset_days);
CREATE INDEX IF NOT EXISTS idx_fin_reminder_rules_org ON orbity.fin_reminder_rules (org_id) WHERE enabled;
ALTER TABLE orbity.fin_reminder_rules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_reminder_rules_select_own_org" ON orbity.fin_reminder_rules;
CREATE POLICY "fin_reminder_rules_select_own_org" ON orbity.fin_reminder_rules FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('orbity')));
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_reminder_rules;
CREATE POLICY "service_role_bypass" ON orbity.fin_reminder_rules FOR ALL TO service_role USING (true) WITH CHECK (true);

-- The dedup ledger + send log. One row per (receivable, rule, cycle date); written BEFORE the send.
CREATE TABLE IF NOT EXISTS orbity.fin_reminder_log (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    entry_id    UUID NOT NULL REFERENCES orbity.fin_entries(id) ON DELETE CASCADE,
    rule_id     UUID NOT NULL REFERENCES orbity.fin_reminder_rules(id) ON DELETE RESTRICT,
    channel     TEXT NOT NULL CHECK (channel IN ('whatsapp', 'email')),
    offset_days INTEGER NOT NULL,
    cycle_date  DATE NOT NULL,
    status      TEXT NOT NULL DEFAULT 'pending' CONSTRAINT fin_reminder_log_status_check CHECK (status IN ('pending', 'sent', 'failed')),
    attempts    INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    recipient   TEXT NOT NULL,
    message     TEXT NOT NULL,
    last_error  TEXT,
    provider_ref TEXT,
    sent_at     TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_reminder_log_dedup ON orbity.fin_reminder_log (org_id, entry_id, rule_id, cycle_date);
CREATE INDEX IF NOT EXISTS idx_fin_reminder_log_org_created ON orbity.fin_reminder_log (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_fin_reminder_log_retry ON orbity.fin_reminder_log (org_id, cycle_date) WHERE status = 'failed';
ALTER TABLE orbity.fin_reminder_log ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_reminder_log_select_own_org" ON orbity.fin_reminder_log;
CREATE POLICY "fin_reminder_log_select_own_org" ON orbity.fin_reminder_log FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('orbity')));
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_reminder_log;
CREATE POLICY "service_role_bypass" ON orbity.fin_reminder_log FOR ALL TO service_role USING (true) WITH CHECK (true);
